SELECT "order_number", "line_no", "item", "quantity", "on_hand", "outage", "quantity" - "on_hand" AS "short"
FROM (SELECT "t7"."order_number", "t7"."customer", "t7"."channel", "t7"."fulfilling_warehouse", "t7"."value", "t7"."placed_date", "t7"."state", "t7"."line_no", "t7"."item", "t7"."quantity", "t7"."unit_price", "t7"."ext_sales_price", "t7"."warehouse", "t7"."sold_date", "t7"."customer0", "t7"."channel0", "t7"."as_of_date", "t7"."quantity_on_hand", "t7"."_ttrp_g_n8_0", "t7"."_ttrp_g_n8_1", "t7"."_ttrp_d_n8", "t8"."warehouse" AS "warehouse0", "t8"."from_date", "t8"."to_date", "t8"."reason", COALESCE("t7"."quantity_on_hand", 0) AS "on_hand", "t8"."warehouse" IS NOT NULL AS "outage"
        FROM (SELECT "t1"."order_number", "t1"."customer", "t1"."channel", "t1"."fulfilling_warehouse", "t1"."value", "t1"."placed_date", "t1"."state", "t1"."line_no", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."ext_sales_price", "t1"."warehouse", "t1"."sold_date", "t1"."customer0", "t1"."channel0", "t6"."as_of_date", "t6"."quantity_on_hand", "t6"."_ttrp_g_n8_0", "t6"."_ttrp_g_n8_1", "t6"."_ttrp_d_n8"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    LEFT JOIN (SELECT "t2"."as_of_date", "t2"."item", "t2"."warehouse", "t2"."quantity_on_hand", "t2"."_ttrp_g_n8_0", "t2"."_ttrp_g_n8_1", "t2"."_ttrp_d_n8"
                        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN "as_of_date" IS NULL THEN 'n' ELSE 'v' || CAST("as_of_date" AS VARCHAR) END AS "_ttrp_d_n8"
                                FROM "inventory") AS "t2"
                            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN MAX("as_of_date") IS NULL THEN 'n' ELSE 'v' || CAST(MAX("as_of_date") AS VARCHAR) END AS "_ttrp_dm_n8"
                                FROM "inventory"
                                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t5" ON "t2"."_ttrp_g_n8_0" = "t5"."_ttrp_g_n8_0" AND "t2"."_ttrp_g_n8_1" = "t5"."_ttrp_g_n8_1" AND "t2"."_ttrp_d_n8" = "t5"."_ttrp_dm_n8") AS "t6" ON "t1"."item" = "t6"."item" AND "t1"."warehouse" = "t6"."warehouse") AS "t7"
            LEFT JOIN (SELECT *
                FROM "warehouse_outage"
                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t8" ON "t7"."warehouse" = "t8"."warehouse") AS "t9"
WHERE "t9"."outage" OR "t9"."on_hand" < "t9"."quantity"
